from collections import defaultdict
import re

# Ensure we have a fresh phone_token
phone_pw=[a['password'] for a in apis.supervisor.show_account_passwords() if a['account_name']=='phone'][0]
phone_token=apis.phone.login(username='6727300099', password=phone_pw)['access_token']

# Fetch friend+ coworker contacts (paginate fully)
def fetch_contacts(relationship):
    allc=[]
    page=0
    while True:
        resp=apis.phone.search_contacts(access_token=phone_token, query='', relationship=relationship, page_index=page, page_limit=20)
        if not resp:
            break
        allc.extend(resp)
        page+=1
    return allc

friends=fetch_contacts('friend')
coworkers=fetch_contacts('coworker')
contacts_by_phone={}
for c in friends+coworkers:
    pn=c.get('phone_number')
    if pn:
        contacts_by_phone[pn]=c

phone_list=list(contacts_by_phone.keys())
print('friends',len(friends),'coworkers',len(coworkers),'unique_phone_contacts',len(phone_list))
print('phones_sample',phone_list[:10])

# Search all text messages with those contacts and extract promo code-like tokens sent to Katie
katie_phone='6727300099'
arrow_re=re.compile(r'=>\s*([A-Za-z0-9]{4,20})')

code_rows=[]
for pn in phone_list:
    page=0
    while True:
        resp=apis.phone.search_text_messages(access_token=phone_token, phone_number=pn, query='', page_index=page, page_limit=20, sort_by='-created_at')
        if not resp:
            break
        for m in resp:
            msg=m.get('message','')
            receiver_phone=m.get('receiver',{}).get('phone_number')
            sender_phone=m.get('sender',{}).get('phone_number')
            # Only codes received by Katie
            if receiver_phone!=katie_phone:
                continue
            if not re.search(r'(code|promo|coupon|deal|=>)', msg, flags=re.I):
                continue
            codes=arrow_re.findall(msg)
            for code in codes:
                if any(ch.isdigit() for ch in code) or len(code)>=5:
                    code_rows.append({
                        'code':code,
                        'from_name':m['sender']['name'],
                        'from_phone':sender_phone,
                        'sent_at':m['sent_at'],
                        'message':msg
                    })
        page+=1

# Deduplicate by (code, from_phone)
seen=set(); unique=[]
for r in code_rows:
    key=(r['code'],r['from_phone'],r['sent_at'])
    if key not in seen:
        seen.add(key)
        unique.append(r)

# Keep newest per code
best_by_code={}
for r in unique:
    c=r['code']
    if c not in best_by_code or r['sent_at']>best_by_code[c]['sent_at']:
        best_by_code[c]=r

best_codes=sorted(best_by_code.values(), key=lambda r:r['sent_at'], reverse=True)
print('promo codes sent to Katie found',len(best_codes))
for r in best_codes:
    print(r['code'],'from',r['from_name'],'sent_at',r['sent_at'],'snippet',r['message'][:60].replace('\n',' '))

